// Recursive Mutex Declaration
std::recursive_mutex r_mtx;
int recursion_level = 0;

void safe_recursive_call(int depth) {
    if (depth <= 0) return;
    std::lock_guard<std::recursive_mutex> lock(r_mtx);
    recursion_level++;
    safe_recursive_call(depth - 1);
    // Ownership counter decreases on destruction
}

// Ownership Tracking Mechanism (Internal concept)
struct internal_state {
    std::thread::id owner_id;
    int recursion_count;
};
